#pragma once
#include <GLES2/gl2.h>
#include <cstring>
#include "gl_batch.h"

struct CharInfo {
    float u0, v0, u1, v1;
    float w, h, advance;
};

class FontAtlas {
public:
    // Upload font atlas texture generated by Java Canvas
    // rgba      — ARGB_8888 bitmap bytes (atlasW * atlasH * 4)
    // charWidths  — pixel width of each of the 96 printable ASCII chars (32..127)
    // charOffsets — x pixel offset of each char in the atlas
    // charH       — pixel height of a character cell
    // atlasTexW   — total used width of atlas (for UV normalization)
    void upload(const uint8_t* rgba, int atlasW, int atlasH,
                const float* charWidths, const float* charOffsets,
                float charH, float atlasTexW) {
        if (_tex) { glDeleteTextures(1, &_tex); _tex = 0; }

        glGenTextures(1, &_tex);
        glBindTexture(GL_TEXTURE_2D, _tex);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
        glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, atlasW, atlasH, 0,
                     GL_RGBA, GL_UNSIGNED_BYTE, rgba);
        glBindTexture(GL_TEXTURE_2D, 0);

        _charH = charH;
        float invW = 1.f / (float)atlasW;
        float invH = 1.f / (float)atlasH;

        for (int i = 0; i < 96; i++) {
            float xOff = charOffsets[i];
            float cw   = charWidths[i];
            _chars[i].u0      = xOff * invW;
            _chars[i].v0      = 0.f;
            _chars[i].u1      = (xOff + cw) * invW;
            _chars[i].v1      = charH * invH;
            _chars[i].w       = cw;
            _chars[i].h       = charH;
            _chars[i].advance = cw + 2.f; // +2 pixel gap between chars
        }
    }

    float measureText(const char* str, float scale = 1.f) const {
        float w = 0.f;
        for (; *str; ++str) {
            int idx = (unsigned char)*str - 32;
            if (idx < 0 || idx >= 96) continue;
            w += _chars[idx].advance * scale;
        }
        return w;
    }

    void drawTextCentered(GlBatch& batch, const char* str,
                          float cx, float y,
                          float scale,
                          float r, float g, float b, float a) const {
        float tw = measureText(str, scale);
        drawText(batch, str, cx - tw * 0.5f, y, scale, r, g, b, a);
    }

    void drawText(GlBatch& batch, const char* str,
                  float x, float y,
                  float scale,
                  float r, float g, float b, float a) const {
        if (!_tex) return;
        glActiveTexture(GL_TEXTURE0);
        glBindTexture(GL_TEXTURE_2D, _tex);
        float cx = x;
        for (; *str; ++str) {
            int idx = (unsigned char)*str - 32;
            if (idx < 0 || idx >= 96) { cx += 6.f * scale; continue; }
            const CharInfo& ci = _chars[idx];
            batch.texQuad(cx, y,
                          ci.w * scale, ci.h * scale,
                          ci.u0, ci.v0, ci.u1, ci.v1,
                          r, g, b, a);
            cx += ci.advance * scale;
        }
    }

    GLuint texId() const { return _tex; }
    bool   ready() const { return _tex != 0; }

private:
    GLuint   _tex = 0;
    CharInfo _chars[96]{};
    float    _charH = 0.f;
};
